include "globals.mzn";

% Entity axis
int: N = 5;
set of int: HOUSE = 1..N;

% Attribute enums
enum NATIONALITY = {Englishman, Spaniard, Ukrainian, Norwegian, Japanese};
enum COLOR = {Red, Green, Ivory, Yellow, Blue};
enum DRINK = {Coffee, Tea, Milk, OrangeJuice, Water};
enum CIGARETTE = {OldGold, Kools, Chesterfields, LuckyStrike, Parliaments};
enum PET = {Dog, Snails, Fox, Horse, Zebra};

% Decision variables
array[HOUSE] of var NATIONALITY: nationality;
array[HOUSE] of var COLOR: color;
array[HOUSE] of var DRINK: drink;
array[HOUSE] of var CIGARETTE: cigarette;
array[HOUSE] of var PET: pet;

% All values used exactly once
constraint alldifferent(nationality);
constraint alldifferent(color);
constraint alldifferent(drink);
constraint alldifferent(cigarette);
constraint alldifferent(pet);

% Clue 1: The Englishman lives in the red house
constraint exists(h in HOUSE)(nationality[h] = Englishman /\ color[h] = Red);

% Clue 2: The Spaniard owns the dog
constraint exists(h in HOUSE)(nationality[h] = Spaniard /\ pet[h] = Dog);

% Clue 3: Coffee is drunk in the green house
constraint exists(h in HOUSE)(drink[h] = Coffee /\ color[h] = Green);

% Clue 4: The Ukrainian drinks tea
constraint exists(h in HOUSE)(nationality[h] = Ukrainian /\ drink[h] = Tea);

% Clue 5: The green house is immediately to the right of the ivory house
constraint exists(h in HOUSE where h < N)(color[h] = Ivory /\ color[h+1] = Green);

% Clue 6: The Old Gold smoker owns snails
constraint exists(h in HOUSE)(cigarette[h] = OldGold /\ pet[h] = Snails);

% Clue 7: Kools are smoked in the yellow house
constraint exists(h in HOUSE)(cigarette[h] = Kools /\ color[h] = Yellow);

% Clue 8: Milk is drunk in the middle house
constraint drink[3] = Milk;

% Clue 9: The Norwegian lives in the first house
constraint nationality[1] = Norwegian;

% Clue 10: The man who smokes Chesterfields lives in the house next to the man with the fox
constraint exists(h in HOUSE)(cigarette[h] = Chesterfields /\ ((h > 1 /\ pet[h-1] = Fox) \/ (h < N /\ pet[h+1] = Fox)));

% Clue 11: Kools are smoked in the house next to the house where the horse is kept
constraint exists(h in HOUSE)(cigarette[h] = Kools /\ ((h > 1 /\ pet[h-1] = Horse) \/ (h < N /\ pet[h+1] = Horse)));

% Clue 12: The Lucky Strike smoker drinks orange juice
constraint exists(h in HOUSE)(cigarette[h] = LuckyStrike /\ drink[h] = OrangeJuice);

% Clue 13: The Japanese smokes Parliaments
constraint exists(h in HOUSE)(nationality[h] = Japanese /\ cigarette[h] = Parliaments);

% Clue 14: The Norwegian lives next to the blue house
constraint exists(h in HOUSE)(nationality[h] = Norwegian /\ ((h > 1 /\ color[h-1] = Blue) \/ (h < N /\ color[h+1] = Blue)));

solve satisfy;

