enum ENTITY = {South, Pedestrian, East, North, West};

% Decision variables: order in which each entity goes through
array[ENTITY] of var 1..5: order;

% All entities go in different positions
constraint alldifferent(order);

% Arrival times (1 = earliest, 3 = latest)
array[ENTITY] of int: arrival = [1, 2, 2, 3, 3];

% Rule 1: Pedestrian at eastern crosswalk goes before East car
constraint order[Pedestrian] < order[East];

% Rule 2: Earlier arrivals go first (with Rule 1 exception already handled)
% South (arrival 1) goes before Pedestrian and East (arrival 2)
constraint order[South] < order[Pedestrian];
constraint order[South] < order[East];

% Pedestrian and East (arrival 2) go before North and West (arrival 3)
constraint order[Pedestrian] < order[North];
constraint order[Pedestrian] < order[West];
constraint order[East] < order[North];
constraint order[East] < order[West];

% Rule 3: North vs West tie-breaker (both arrival 3)
% Clockwise priority: North before West
constraint order[North] < order[West];

