enum PERSON = {Priya, Sam};
enum OUTCOME = {Denied, Approved, CounterOffer};

% Given facts
array[PERSON] of int: credit_score = [680, 750];
int: combined_monthly_income = 9000;
int: combined_monthly_debt = 3200;
bool: requested_exceeds_limit = true;

% Decision variables
var int: couple_credit_score;
var float: dti_ratio;
var OUTCOME: outcome;

% Couple's credit tier uses the lower score
constraint couple_credit_score = min(credit_score);

% Calculate DTI ratio
constraint dti_ratio = int2float(combined_monthly_debt) / int2float(combined_monthly_income);

% Rule 1: If credit score below 600, loan is Denied
constraint (couple_credit_score < 600) -> (outcome = Denied);

% Rule 2: If DTI ratio exceeds 43%, loan is Denied
constraint (dti_ratio > 0.43) -> (outcome = Denied);

% Rule 3: If not denied and requested amount within policy limits, Approved
constraint (couple_credit_score >= 600 /\ dti_ratio <= 0.43 /\ not requested_exceeds_limit) -> (outcome = Approved);

% Rule 4: If not denied and requested amount exceeds policy limits, Counter-Offer
constraint (couple_credit_score >= 600 /\ dti_ratio <= 0.43 /\ requested_exceeds_limit) -> (outcome = CounterOffer);

solve satisfy;

